"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["65218"],{95956(e){e.exports=JSON.parse('{"id":"F520","slug":"iqr-outlier-fences","name":"IQR Outlier Fences","subject":"Data, Statistics & Computational Skills","section":"Data and coding workflow","topic":"Data and coding workflow","level":"Beginner","aliases":["data and coding workflow","data cleaning","Tukey fences","detect outliers","interquartile range"],"formula":{"latex":"IQR=Q_{3}-Q_{1},\\\\quad \\\\text{Fences}=Q_{1}-k\\\\cdot IQR,\\\\; Q_{3}+k\\\\cdot IQR","also":[],"text":"IQR = third quartile - first quartile; Lower fence = Q1 - k x IQR; Upper fence = Q3 + k x IQR; values outside the fences are flagged (k = 1.5 is the usual choice)"},"symbols":[{"symbol":"Q_1, Q_3","meaning":"25th and 75th percentiles of the data","unit":"same as data"},{"symbol":"IQR","meaning":"Interquartile range: the spread of the middle half of the data","unit":"same as data"},{"symbol":"k","meaning":"Fence multiplier. 1.5 flags mild outliers, 3 flags extreme ones","unit":"number"}],"when_to_use":"Use it as a first pass in cleaning data, to find values that look like errors or extreme events, such as a price typed with an extra digit. Quartiles ignore extreme values, so one bad point cannot hide itself the way it can in a mean and standard deviation test. A flagged value is a prompt to investigate, not an instruction to delete: real crashes are outliers too.","worked_example":{"problem":"Fifteen daily values are in the calculator. Which are outliers with k = 1.5?","inputs":{"d":[12,15,14,10,18,13,16,11,14,95,15,13,12,17,14],"k":1.5},"steps":[{"label":"First quartile (25th percentile)","working":null,"value":"12.50"},{"label":"Third quartile (75th percentile)","working":null,"value":"15.50"},{"label":"IQR = Q3 - Q1","working":"15.5-12.5","value":"3.00"},{"label":"Lower fence = Q1 - k x IQR","working":"12.5-1.5 x 3","value":"8.00"},{"label":"Upper fence = Q3 + k x IQR","working":"15.5+1.5 x 3","value":"20.00"},{"label":"Values outside the fences","working":null,"value":"1"},{"label":"Mean with all values","working":null,"value":"19.27"},{"label":"Mean without the flagged values","working":null,"value":"13.86"}],"answer":"The quartiles are 12.50 and 15.50, so the IQR is 3.00 and the fences are 8.00 and 20.00. 1 value lies outside, the 95. The mean is 19.27 with it and 13.86 without, which shows how much one point can move it."},"calculator":{"available":true,"inputs":[{"id":"d","label":"Data values","unit":"","type":"list","default":[12,15,14,10,18,13,16,11,14,95,15,13,12,17,14],"hint":""},{"id":"k","label":"Fence multiplier k","unit":"","type":"number","default":1.5,"hint":""}],"checks":[{"expr":"count(d)>=4 and k>0","message":"Enter at least four values and a multiplier above zero."}],"steps":[{"id":"q1","label":"First quartile (25th percentile)","expr":"quantile(d, 0.25)","format":"num2"},{"id":"q3","label":"Third quartile (75th percentile)","expr":"quantile(d, 0.75)","format":"num2"},{"id":"iqr","label":"IQR = Q3 - Q1","expr":"q3-q1","format":"num2"},{"id":"lo","label":"Lower fence = Q1 - k x IQR","expr":"q1-k*iqr","format":"num2"},{"id":"hi","label":"Upper fence = Q3 + k x IQR","expr":"q3+k*iqr","format":"num2"},{"id":"nout","label":"Values outside the fences","expr":"outcount(d, lo, hi)","format":"num0"},{"id":"mean","label":"Mean with all values","expr":"mean(d)","format":"num2"},{"id":"mean2","label":"Mean without the flagged values","expr":"trimmean(d, lo, hi)","format":"num2"}],"results":["lo","hi","nout"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"q1":12.5,"q3":15.5,"iqr":3,"lo":8,"hi":20,"nout":1,"mean":19.266666666666666,"mean2":13.857142857142858}},"finder":{"finds":"Values that sit far outside the bulk of the data","needs":"A list of values"},"related":[{"slug":"sample-size-mean","name":"Sample Size for Estimating a Mean"},{"slug":"hypothesis-test-two-means","name":"Two-Sample Z-Test for a Difference in Means"},{"slug":"confidence-interval-mean","name":"Confidence Interval for a Mean"}],"related_ids":["F518","F519","F060"],"group":"Risk and quantitative methods","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>I</mi><mi>Q</mi><mi>R</mi><mo>=</mo><msub><mi>Q</mi><mn>3</mn></msub><mo>\u2212</mo><msub><mi>Q</mi><mn>1</mn></msub><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Fences</mtext><mo>=</mo><msub><mi>Q</mi><mn>1</mn></msub><mo>\u2212</mo><mi>k</mi><mo>\u22C5</mo><mi>I</mi><mi>Q</mi><mi>R</mi><mo separator=\\"true\\">,</mo><mtext>\u2005\u200A</mtext><msub><mi>Q</mi><mn>3</mn></msub><mo>+</mo><mi>k</mi><mo>\u22C5</mo><mi>I</mi><mi>Q</mi><mi>R</mi></mrow><annotation encoding=\\"application/x-tex\\">IQR=Q_{3}-Q_{1},\\\\quad \\\\text{Fences}=Q_{1}-k\\\\cdot IQR,\\\\; Q_{3}+k\\\\cdot IQR</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"underwriting-economics","name":"IPO Underwriting Spread and Greenshoe"},"next":{"slug":"ito-lemma-drift","name":"It\xf4\'s Lemma: Drift and Volatility of a Function"},"lesson":null,"total":522}')}}]);